// POST <contentWorker>/api/save-json          Authorization: Bearer <token>
//
// The important one. Writes ONE JSON document to the content repo.
//
// Applications and properties BOTH go through this — same endpoint, different
// `path`. They are both "a JSON document in the content repo", and one
// endpoint is less to build than two. The request type below is a discriminated
// union, so the path tells you exactly which body to expect.

import type { ApplicationsDocument } from "./models";
import type { PropertiesDocument } from "./getProperties";
import { PATH as APPLICATIONS_PATH } from "./getApplications.ts";
import { PATH as PROPERTIES_PATH } from "./getProperties.ts";

export const METHOD = "POST" as const;
export const PATH = "api/save-json";
export const AUTH = "bearer" as const;

/**
 * The body.
 *
 * A union rather than `{ path: string; content: unknown }` on purpose: the
 * path and the shape are not independent, and typing them together means you
 * cannot write a handler that accepts one with the other.
 */
export type SaveJsonRequest =
  | { path: typeof APPLICATIONS_PATH; content: ApplicationsDocument }
  | { path: typeof PROPERTIES_PATH; content: PropertiesDocument };

export type SaveJsonResponse =
  | { ok: true }
  | {
      ok: false;
      /**
       * Shown to a property manager AS WRITTEN. No sha, no repo name, no
       * token, no stack trace. "Somebody else saved this while you were
       * editing it" is a message; "409 on refs/heads/main" is not.
       */
      error: string;
    };

/**
 * Paths this endpoint may write, and nothing else.
 *
 * This is why it is not a general file writer. An authenticated CMS user is
 * not the same thing as a user who may write anywhere in the repository: a bug
 * or a tampered request must not be able to overwrite site source, a workflow
 * file, or the image manifest.
 *
 * The browser checks this too, so it fails early with the same wording. That
 * copy is a convenience and NOT a security boundary — check it again here.
 */
export const ALLOWED_PATHS = [APPLICATIONS_PATH, PROPERTIES_PATH] as const;

/** If you prefer a rule to a list. */
export const ALLOWED_DIRECTORIES = ["applications", "properties"] as const;

/** No dots beyond the extension, so no traversal and no extension games. */
export const FILENAME_PATTERN = "^[a-z0-9][a-z0-9-]{0,63}\.json$";

/**
 * How the CMS reads your reply, so you know what matters:
 *
 *   200            treated as saved.
 *   404            treated as "not deployed yet" and said so in plain words.
 *   other non-2xx  `error` is shown if the body is JSON, else the body text.
 *   network fail   treated as "could not reach the save service".
 *
 * NEVER return 200 for a write that did not happen. The interface believes
 * you, and a save that silently did nothing is the worst outcome available —
 * the person finds out days later, with the work gone.
 */
export type SaveJsonNotes = never;
