// GET <contentRepo>/applications/applications.json
//
// The application FORMS — the questions a renter is asked. Not the answers;
// those are leads, see getLead.ts.
//
// No auth. This is a public JSON file; it can literally be a file on GitHub
// Pages. A 404 is FINE and expected before the first save — the CMS falls back
// to a bundled starter form and says so.

import type { ApplicationsDocument } from "./models";

export const METHOD = "GET" as const;
export const PATH = "applications/applications.json";
export const AUTH = "none" as const;

/** No request body. */
export type GetApplicationsRequest = void;

/** The response body, verbatim. */
export type GetApplicationsResponse = ApplicationsDocument;

/**
 * Invariants the document always satisfies, if you validate server-side:
 *
 *   • `activeId` names a live application, or is "" only when there are none.
 *   • A deleted form is NOT removed — it gets `deletedAt` (ISO string) and the
 *     browser purges it after 30 days. That is the Trash. Store what you are
 *     given and do not tidy it.
 *   • `version` is 1 today.
 *
 * Nothing needs generating server-side: ids, timestamps and ordering are all
 * decided in the browser and arrive complete.
 */
export type GetApplicationsNotes = never;
