// The Supabase REST client.
//
// Deliberately fetch-based rather than @supabase/supabase-js. The three
// surfaces this CMS needs — PostgREST for the tables, GoTrue for sign-in,
// Storage for images — are all plain REST, every other adapter in this project
// is already a thin fetch wrapper, and the test runner has no dependencies at
// all. Pulling a large SDK into a Gatsby bundle to send four kinds of request
// would be the odd choice here, not the safe one.
//
// Everything above this file talks to the SAME adapter interfaces it always
// has. Supabase is an implementation of those, not a rewrite of them.

import { SUPABASE_ANON_KEY } from "../../config/supabase--anon-key.ts";
import { SUPABASE_URL } from "../../config/supabase--url.ts";

/**
 * Whether Supabase is actually usable.
 *
 * Both values have to be present. A half-configured project would fail every
 * request and read to the user as a broken CMS rather than an unfinished one,
 * so the toggle that selects Supabase checks this first and falls back to demo
 * storage when it is false.
 */
export const supabaseConfigured = (): boolean =>
  Boolean(SUPABASE_URL.trim()) && Boolean(SUPABASE_ANON_KEY.trim());

/** Where the signed-in session lives. Same convention as the rest: kr:… */
const SESSION_KEY = "kr:supabase:session:v1";

export type SupabaseSession = {
  access_token: string;
  refresh_token: string;
  /** Epoch SECONDS, as GoTrue returns it. */
  expires_at?: number;
  user?: { id: string; email?: string };
};

/* ── the stored session ──────────────────────────────────── */

export function readSession(): SupabaseSession | null {
  if (typeof window === "undefined") return null;

  try {
    const raw = window.localStorage.getItem(SESSION_KEY);
    if (!raw) return null;

    const parsed = JSON.parse(raw) as SupabaseSession;
    return parsed?.access_token ? parsed : null;
  } catch {
    return null;
  }
}

export function writeSession(session: SupabaseSession | null): void {
  if (typeof window === "undefined") return;

  try {
    if (session) window.localStorage.setItem(SESSION_KEY, JSON.stringify(session));
    else window.localStorage.removeItem(SESSION_KEY);
  } catch {
    /* Private browsing. The session simply does not persist; the user stays
       signed in for this tab and signs in again next time, which is a great
       deal better than the CMS refusing to load. */
  }
}

/** Sixty seconds of slack, so a token does not expire mid-request. */
const isExpired = (session: SupabaseSession): boolean =>
  typeof session.expires_at === "number" &&
  session.expires_at * 1000 - 60_000 < Date.now();

/**
 * A valid access token, refreshing it first if it is about to expire.
 *
 * Returns null when nobody is signed in — callers turn that into "you are
 * signed out", never into a silent failure.
 */
export async function accessToken(): Promise<string | null> {
  const session = readSession();
  if (!session) return null;
  if (!isExpired(session)) return session.access_token;

  try {
    const res = await fetch(
      `${SUPABASE_URL}/auth/v1/token?grant_type=refresh_token`,
      {
        method: "POST",
        headers: {
          apikey: SUPABASE_ANON_KEY,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ refresh_token: session.refresh_token }),
      }
    );

    if (!res.ok) {
      /* The refresh token is spent or revoked. Clearing it is what turns this
         into a clean "sign in again" rather than a loop of failed retries. */
      writeSession(null);
      return null;
    }

    const next = (await res.json()) as SupabaseSession;
    writeSession(next);
    return next.access_token;
  } catch {
    /* Offline. The existing token may still work; let the caller find out
       rather than signing somebody out because their wifi dropped. */
    return session.access_token;
  }
}

/* ── requests ────────────────────────────────────────────── */

export type SupabaseError = {
  /** Plain English, safe to show a property manager as written. */
  message: string;
  status: number;
};

export type SupabaseResult<T> =
  | { ok: true; data: T }
  | { ok: false; error: SupabaseError };

/**
 * Turns a failed response into something a person can act on.
 *
 * Postgres error text is written for developers — "new row violates row-level
 * security policy for table cms_documents" tells a property manager nothing
 * they can do anything about. The common cases are named; anything else falls
 * back to a plain sentence rather than leaking the raw body.
 */
function explain(status: number, body: unknown): SupabaseError {
  const raw =
    typeof body === "object" && body !== null
      ? String((body as { message?: string; error?: string }).message ??
          (body as { error?: string }).error ?? "")
      : String(body ?? "");

  if (status === 401 || status === 403) {
    return {
      status,
      message: /row-level security|permission/i.test(raw)
        ? "Your account does not have permission to change this. Ask whoever set up the site to check your access."
        : "You are signed out. Sign in again to save changes.",
    };
  }

  if (status === 404) {
    return {
      status,
      message:
        "The site's database is not set up yet, so there is nowhere to save to. Nothing was saved.",
    };
  }

  if (status === 409) {
    return {
      status,
      message:
        "Somebody else saved this while you were editing it. Reload the page to see their version.",
    };
  }

  return {
    status,
    message: raw.trim()
      ? `That could not be saved: ${raw.trim()}`
      : `That could not be saved (error ${status}). Nothing was saved.`,
  };
}

export type RequestOptions = {
  method?: "GET" | "POST" | "PATCH" | "DELETE";
  /** Extra PostgREST headers, e.g. Prefer. */
  headers?: Record<string, string>;
  body?: unknown;
  /** Send the signed-in user's token. Reads that are public can skip it. */
  authenticated?: boolean;
};

/**
 * One request to Supabase.
 *
 * Never throws. Every caller gets a result it has to look at, which is what
 * stops a failed write being mistaken for a successful one — the single most
 * damaging thing a CMS can get wrong.
 */
export async function supabaseRequest<T>(
  path: string,
  options: RequestOptions = {}
): Promise<SupabaseResult<T>> {
  if (!supabaseConfigured()) {
    return {
      ok: false,
      error: {
        status: 0,
        message:
          "The site's database is not connected yet, so this cannot be saved.",
      },
    };
  }

  const { method = "GET", headers = {}, body, authenticated = true } = options;

  const auth: Record<string, string> = {};

  if (authenticated) {
    const token = await accessToken();
    if (token) auth.Authorization = `Bearer ${token}`;
  }

  let res: Response;

  try {
    res = await fetch(`${SUPABASE_URL}${path}`, {
      method,
      cache: "no-store",
      signal: AbortSignal.timeout(15_000),
      headers: {
        apikey: SUPABASE_ANON_KEY,
        "Content-Type": "application/json",
        ...auth,
        ...headers,
      },
      body: body === undefined ? undefined : JSON.stringify(body),
    });
  } catch {
    return {
      ok: false,
      error: {
        status: 0,
        message:
          "Could not reach the site's database. Check your connection and try again — nothing was saved.",
      },
    };
  }

  const text = await res.text();

  let parsed: unknown = null;
  if (text) {
    try {
      parsed = JSON.parse(text);
    } catch {
      parsed = text;
    }
  }

  if (!res.ok) return { ok: false, error: explain(res.status, parsed) };

  return { ok: true, data: parsed as T };
}
